    a=json.loads(lines[i])
    a.update(kw)
    lines[i]=json.dumps(a, ensure_ascii=False)
for i,l in enumerate(lines):
    a=json.loads(l)
    sid=a['segment_id']
    if sid=='R20-016':
        setf(i, quote="Let's check for `webRequest` patterns in `service_worker.js` using `bash` and `grep -o` to see all occurrences.")
