        setf(i, quote='grep -o \\"chrome\\\\.webRequest\\\\.[^;]*\\" /work/run/out/service_worker.js')
    elif sid=='R20-024':
        setf(i, segment_id='R20-026', quote="returned no output. Maybe it's not used.")
    elif sid=='R20-036':
        setf(i, quote='grep -E \\"chrome\\\\.extension|chrome\\\\.browserAction|chrome\\\\.tabs\\\\.executeScript\\" /work/run/out/popup.bundle.js')
    elif sid=='R20-040':
        setf(i, quote='If `service_worker.js` is the result of bundling those scripts, then `background.html` is obsolete.')
    elif sid=='R20-056':
        setf(i, quote='grep -o \\"eval(\\" /work/run/out/popup.bundle.js | wc -l')
    elif sid=='R20-070':
        setf(i, segment_id='R20-071', quote='Fixed service_worker.js.')
    elif sid=='R20-075':
        setf(i, segment_id='R20-074')
